Word Use

Most frequent words per country


Code
tokens_clean |&gt;
  count(country, word, sort = TRUE) |&gt;
  group_by(country) |&gt;
  slice_max(n, n = 60, with_ties = FALSE) |&gt;
  mutate(rel = n / max(n)) |&gt;          # size relative to each country's top word,
  ungroup() |&gt;                         # so small countries stay readable
  ggplot(aes(label = word, size = rel, color = rel)) +
  geom_text_wordcloud(rm_outside = TRUE, seed = 42) +
  scale_size_area(max_size = 10) +
  scale_color_viridis_c(option = "plasma", end = 0.85) +
  facet_wrap(~country, ncol = 3) +
  theme_minimal(base_size = 12) +
  theme(strip.text = element_text(face = "bold", size = 13)) +
  labs(title = "Most frequent words per country (original language, stopwords removed)",
       subtitle = "Word size relative to each country's most frequent word")









Every country’s coverage is organised around the same actors: Iran, Israel, Trump and the United States, then the military vocabulary of strikes, missiles and forces. The clouds show who is covered, which is much the same everywhere, not how.


Distinctive words among English-language sources (TF-IDF)


Code
tokens_clean |&gt;
  filter(country %in% english_sources) |&gt;
  add_count(country, word, name = "n") |&gt;
  group_by(country, word) |&gt;
  filter(n_distinct(article_id) &gt;= 5) |&gt;    # ignore names that appear in one or two articles
  summarise(n = first(n), .groups = "drop") |&gt;
  bind_tf_idf(word, country, n) |&gt;
  group_by(country) |&gt;
  slice_max(tf_idf, n = 12, with_ties = FALSE) |&gt;
  ungroup() |&gt;
  mutate(word = reorder_within(word, tf_idf, country)) |&gt;
  ggplot(aes(x = tf_idf, y = word, fill = country)) +
  geom_col(show.legend = FALSE) +
  facet_wrap(~country, scales = "free", ncol = 3) +
  scale_y_reordered() +
  scale_fill_viridis_d(option = "turbo") +
  labs(
    title = "Most distinctive words per source, English-language sources only (TF-IDF)",
    subtitle = "Each source compared with the other four; words used by all five score zero; words in at least 5 articles",
    x = "TF-IDF", y = NULL
  ) +
  theme_minimal(base_size = 11) +
  theme(strip.text = element_text(face = "bold"))









Restricting the comparison to English-language sources removes the language effect, which otherwise dominates TF-IDF. What remains is mostly each source’s home angle: Canadian politics and markets (Carney, Poilievre, the TSX), British defence (RAF, Akrotiri, HMS), US domestic politics (GOP, senators, the FBI), Israeli security and diplomacy (IDF, normalization, the shekel as NIS). Spelling conventions (defence, programme) also register. Al Jazeera is the only source with genocide and genocidal among its distinctive words.


Most common two-word phrases


Code
texts |&gt;
  unnest_tokens(bigram, full_text, token = "ngrams", n = 2) |&gt;
  filter(!is.na(bigram)) |&gt;
  separate(bigram, into = c("word1", "word2"), sep = " ") |&gt;
  mutate(word1 = strip_elision(word1), word2 = strip_elision(word2)) |&gt;
  anti_join(all_stopwords, by = c("word1" = "word", "language")) |&gt;
  anti_join(all_stopwords, by = c("word2" = "word", "language")) |&gt;
  filter(nchar(word1) &gt; 2, nchar(word2) &gt; 2,
         !str_detect(word1, "^\\d+$"), !str_detect(word2, "^\\d+$")) |&gt;
  unite(bigram, word1, word2, sep = " ") |&gt;
  count(country, bigram, sort = TRUE) |&gt;
  group_by(country) |&gt;
  slice_max(n, n = 10, with_ties = FALSE) |&gt;
  ungroup() |&gt;
  mutate(bigram = reorder_within(bigram, n, country)) |&gt;
  ggplot(aes(x = n, y = bigram, fill = country)) +
  geom_col(show.legend = FALSE) +
  facet_wrap(~country, scales = "free", ncol = 3) +
  scale_y_reordered() +
  scale_fill_viridis_d(option = "turbo") +
  labs(title = "Most common two-word phrases per country", x = "Count", y = NULL) +
  theme_minimal(base_size = 11) +
  theme(strip.text = element_text(face = "bold"))









Donald Trump is among the top three phrases in every country, Iran’s supreme leader or the Islamic Republic appear everywhere, and Middle East leads in most. The phrases are names of people, places and institutions; few carry any evaluation, which is one reason word counts alone say little about tone.
